bool CollectPlotTopologyRecord(CvPlot& plot, PlotTopologyRecord& out)
{
    bool valid = true;
    // Area identifier.
    out.area = static_cast<i32>(plot.getArea());
    // Landmass identifier.
    out.landmass = static_cast<i32>(plot.getLandmass());
    // Terrain type.
    {
        const i32 checkedTerrainType = static_cast<i32>(plot.getTerrainType());
        if (checkedTerrainType < -128 || checkedTerrainType > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotTopologyRecord", "terrainType", checkedTerrainType, -128, 127);
            valid = false;
        }
        else
        {
            out.terrainType = static_cast<i8>(checkedTerrainType);
        }
    }
    // Flat, hill, mountain, or water plot type.
    {
        const i32 checkedPlotType = static_cast<i32>(plot.getPlotType());
        if (checkedPlotType < -128 || checkedPlotType > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotTopologyRecord", "plotType", checkedPlotType, -128, 127);
            valid = false;
        }
        else
        {
            out.plotType = static_cast<i8>(checkedPlotType);
        }
    }
    // Hill flag.
    out.hills = (plot.isHills()) ? 1 : 0;
    // Mountain flag.
    out.mountain = (plot.isMountain()) ? 1 : 0;
    // Water flag.
    out.water = (plot.isWater()) ? 1 : 0;
    // Deep-water flag.
    out.deepWater = (plot.isDeepWater()) ? 1 : 0;
    // Lake flag.
    out.lake = (plot.isLake()) ? 1 : 0;
    // Coastal-land flag. The city coastal answer reads this flag at the city plot.
    out.coastalLand = (plot.isCoastalLand()) ? 1 : 0;
    // River flag.
    out.river = (plot.isRiver()) ? 1 : 0;
    // Per-direction river-crossing flags.
    for (int index = 0; index < 1; ++index) {
        out.riverCrossing[index] = 0;
    }
    if ((NUM_DIRECTION_TYPES) > VoxRlDirectionCapacity) {
        return false;
    }
    for (int index = 0; index < (NUM_DIRECTION_TYPES); ++index) {
        if (plot.isRiverCrossing(static_cast<DirectionTypes>(index))) {
            out.riverCrossing[index / 8] = static_cast<u8>(out.riverCrossing[index / 8] | (1 << (index % 8)));
        }
    }
    // Northeast river flow.
    out.northEastRiver = (plot.isNEOfRiver()) ? 1 : 0;
    // West river flow.
    out.westRiver = (plot.isWOfRiver()) ? 1 : 0;
    // Northwest river flow.
    out.northWestRiver = (plot.isNWOfRiver()) ? 1 : 0;
    // River crossing count.
    {
        const i32 checkedRiverCrossingCount = static_cast<i32>(plot.getRiverCrossingCount());
        if (checkedRiverCrossingCount < 0 || checkedRiverCrossingCount > 6)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotTopologyRecord", "riverCrossingCount", checkedRiverCrossingCount, 0, 6);
            valid = false;
        }
        else
        {
            out.riverCrossingCount = static_cast<u8>(checkedRiverCrossingCount);
        }
    }
    // Native return type is char.
    {
        const i32 checkedContinentType = static_cast<i32>(plot.GetContinentType());
        if (checkedContinentType < -128 || checkedContinentType > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotTopologyRecord", "continentType", checkedContinentType, -128, 127);
            valid = false;
        }
        else
        {
            out.continentType = static_cast<i8>(checkedContinentType);
        }
    }
    // Lowercase native accessor.
    out.roughGround = (plot.isRoughGround()) ? 1 : 0;
    return valid;
}

