bool CollectWorldGameStateRecord(WorldGameStateRecord& out)
{
    bool valid = true;
    // Native GameStateTypes value: GAMESTATE_ON, GAMESTATE_OVER, or GAMESTATE_EXTENDED.
    // gameState has no generated assignment because its capture mode is builder.
    // Absolute game-turn approximation of elapsed turns. Later-era starts include an era-dependent turn offset while native elapsed turns begin at zero.
    {
        i32 clampedElapsedGameTurns = static_cast<i32>(GC.getGame().getGameTurn());
        if (clampedElapsedGameTurns < -32768) clampedElapsedGameTurns = -32768;
        if (clampedElapsedGameTurns > 32767) clampedElapsedGameTurns = 32767;
        out.elapsedGameTurns = static_cast<i16>(clampedElapsedGameTurns);
    }
    // maxTurns captured for Batch 2.
    {
        i32 clampedMaxTurns = static_cast<i32>(GC.getGame().getMaxTurns());
        if (clampedMaxTurns < -32768) clampedMaxTurns = -32768;
        if (clampedMaxTurns > 32767) clampedMaxTurns = 32767;
        out.maxTurns = static_cast<i16>(clampedMaxTurns);
    }
    // Cached native game-era value at the WORLD or REQUEST capture boundary.
    {
        i32 clampedCurrentEra = static_cast<i32>(GC.getGame().getCurrentEra());
        if (clampedCurrentEra < -32768) clampedCurrentEra = -32768;
        if (clampedCurrentEra > 32767) clampedCurrentEra = 32767;
        out.currentEra = static_cast<i16>(clampedCurrentEra);
    }
    return valid;
}

