bool CollectPlotCaptureRecord(CvPlot& plot, PlotCaptureRecord& out)
{
    bool valid = true;
    // Quantity of the fixed resource on this tile.
    out.resourceCount = static_cast<i32>(plot.getNumResource());
    // Effective working-city identity after the native override. The core row carries this reference as a token into the block's city reference table.
    out.effectiveOwningCityId = static_cast<i32>(plot.getEffectiveOwningCity() ? plot.getEffectiveOwningCity()->GetID() : -1);
    // Improvement type, encoded into the core row as a bounded one-byte value.
    out.improvementType = static_cast<i32>(plot.getImprovementType());
    // Resource type using native defaults, encoded into the core row as a bounded one-byte value.
    out.resourceType = static_cast<i32>(plot.getResourceType());
    // Recon count, carried in a sparse counter row.
    out.reconCount = static_cast<i32>(plot.getReconCount());
    // Extra path movement cost, carried in a sparse counter row.
    out.extraMovePathCost = static_cast<i32>(plot.getExtraMovePathCost());
    // Stacking-limit bonus from the improvement, carried in a sparse counter row; zero when the stacking-rules mod flag is off.
    out.unitIncrement = static_cast<i32>(plot.getAdditionalUnitsFromImprovement());
    // Second owner-qualified owning-city reference component. The core row carries this reference as a token into the block's city reference table.
    out.owningCityId = static_cast<i32>(plot.getOwningCity() ? plot.getOwningCity()->GetID() : -1);
    // Effective working-city owner after the native override; encoded with the identity as one city reference token.
    {
        const i32 checkedEffectiveOwningCityOwner = static_cast<i32>(plot.getEffectiveOwningCity() ? plot.getEffectiveOwningCity()->getOwner() : NO_PLAYER);
        if (checkedEffectiveOwningCityOwner < -128 || checkedEffectiveOwningCityOwner > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotCaptureRecord", "effectiveOwningCityOwner", checkedEffectiveOwningCityOwner, -128, 127);
            valid = false;
        }
        else
        {
            out.effectiveOwningCityOwner = static_cast<i8>(checkedEffectiveOwningCityOwner);
        }
    }
    // Owning player.
    {
        const i32 checkedOwner = static_cast<i32>(plot.getOwner());
        if (checkedOwner < -128 || checkedOwner > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotCaptureRecord", "owner", checkedOwner, -128, 127);
            valid = false;
        }
        else
        {
            out.owner = static_cast<i8>(checkedOwner);
        }
    }
    // Dynamic feature type.
    {
        const i32 checkedFeatureType = static_cast<i32>(plot.getFeatureType());
        if (checkedFeatureType < -128 || checkedFeatureType > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotCaptureRecord", "featureType", checkedFeatureType, -128, 127);
            valid = false;
        }
        else
        {
            out.featureType = static_cast<i8>(checkedFeatureType);
        }
    }
    // Route type.
    {
        const i32 checkedRouteType = static_cast<i32>(plot.getRouteType());
        if (checkedRouteType < -128 || checkedRouteType > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotCaptureRecord", "routeType", checkedRouteType, -128, 127);
            valid = false;
        }
        else
        {
            out.routeType = static_cast<i8>(checkedRouteType);
        }
    }
    // Team of the player responsible for an unowned route, or NO_TEAM.
    {
        const i32 checkedRouteOwnerTeam = static_cast<i32>(plot.GetPlayerResponsibleForRoute() != NO_PLAYER ? GET_PLAYER(plot.GetPlayerResponsibleForRoute()).getTeam() : NO_TEAM);
        if (checkedRouteOwnerTeam < -128 || checkedRouteOwnerTeam > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotCaptureRecord", "routeOwnerTeam", checkedRouteOwnerTeam, -128, 127);
            valid = false;
        }
        else
        {
            out.routeOwnerTeam = static_cast<i8>(checkedRouteOwnerTeam);
        }
    }
    // Team of the player that built the improvement, or NO_TEAM.
    {
        const i32 checkedImprovementBuilderTeam = static_cast<i32>(plot.GetPlayerThatBuiltImprovement() != NO_PLAYER ? GET_PLAYER(plot.GetPlayerThatBuiltImprovement()).getTeam() : NO_TEAM);
        if (checkedImprovementBuilderTeam < -128 || checkedImprovementBuilderTeam > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotCaptureRecord", "improvementBuilderTeam", checkedImprovementBuilderTeam, -128, 127);
            valid = false;
        }
        else
        {
            out.improvementBuilderTeam = static_cast<i8>(checkedImprovementBuilderTeam);
        }
    }
    // First owner-qualified owning-city reference component; the border-obstacle rule resolves the working city. Encoded with the identity as one city reference token.
    {
        const i32 checkedOwningCityOwner = static_cast<i32>(plot.getOwningCity() ? plot.getOwningCity()->getOwner() : NO_PLAYER);
        if (checkedOwningCityOwner < -128 || checkedOwningCityOwner > 127)
        {
            VoxRlNoteCaptureRangeFailure("range", "PlotCaptureRecord", "owningCityOwner", checkedOwningCityOwner, -128, 127);
            valid = false;
        }
        else
        {
            out.owningCityOwner = static_cast<i8>(checkedOwningCityOwner);
        }
    }
    // Worked state used by adjacent city deep-water damage.
    out.beingWorked = (plot.isBeingWorked()) ? 1 : 0;
    // Improvement pillage state.
    out.improvementPillaged = (plot.IsImprovementPillaged()) ? 1 : 0;
    // Improvement movement passability. The native field is a cache, so the captured value is retained until an invariant test proves an exact derivation.
    out.improvementPassable = (plot.IsImprovementPassable()) ? 1 : 0;
    // Capitalized native accessor.
    out.routePillaged = (plot.IsRoutePillaged()) ? 1 : 0;
    // Whether the player responsible for the route is still alive.
    out.routeOwnerAlive = (plot.GetPlayerResponsibleForRoute() != NO_PLAYER && GET_PLAYER(plot.GetPlayerResponsibleForRoute()).isAlive()) ? 1 : 0;
    // Whether the improvement builder is still alive; the Feitoria rule consults this before its team relation.
    out.improvementBuilderAlive = (plot.GetPlayerThatBuiltImprovement() != NO_PLAYER && GET_PLAYER(plot.GetPlayerThatBuiltImprovement()).isAlive()) ? 1 : 0;
    // Restore-moves flag.
    out.restoreMoves = (plot.IsRestoreMoves()) ? 1 : 0;
    // Free movement edge flag.
    out.freeMoveAcross = (plot.IsFreeMoveAcross()) ? 1 : 0;
    return valid;
}

